fn draw_signed(x: i32, y: i32, v: i32, rgb: i32, sc: i32) {
    if v < 0 {
        host::display::draw_char(x, y, 45, rgb, sc);
        host::display::draw_number(x + sc * 8, y, 0 - v, rgb, sc);
    } else {
        host::display::draw_number(x, y, v, rgb, sc);
    }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    host::display::clear(0x0c0c0c);
    host::display::draw_string(40, 12, "C", 0xffffff, 2);
    host::display::draw_string(150, 12, "F", 0xffffff, 2);
    host::display::draw_line(20, 34, w - 20, 34, 0x606060);
    let mut i: i32 = 0;
    while i < 6 {
        let c: i32 = i * 10 - 10;
        let f: i32 = c * 9 / 5 + 32;
        let y: i32 = 44 + i * 30;
        if i % 2 == 0 {
            host::display::fill_rect(20, y - 4, w - 40, 28, 0x16161c);
        }
        draw_signed(40, y, c, 0xc0e0ff, 2);
        draw_signed(150, y, f, 0xffd0a0, 2);
        i = i + 1;
    }
    host::display::draw_string(20, 240, "F = C*9/5+32", 0x808080, 1);
    host::display::present();
}
